// generated by polka.codes
export type ParseOutputResult<T> = { success: true; data: T } | { success: false; error?: string }

export const parseJsonFromMarkdown = (markdown: string): ParseOutputResult<any> => {
  const text = markdown.trim()
  const fence = /^```(?:json)?[^\S\r\n]*\r?\n([\s\S]*)\r?\n```$/i.exec(text)

  try {
    return { success: true, data: JSON.parse(fence?.[1] ?? text) }
  } catch {
    return { success: false, error: 'No JSON object found in the string.' }
  }
}
